import * as THREE from './vendor/three.module.js';
export class Effects {
 constructor(scene){this.scene=scene;this.pool=[];this.cursor=0;this.numbers=[];this.flashes=[];this.shake=0;this.hitStop=0;const geo=new THREE.TetrahedronGeometry(1);this.colors=['#ffe9b1','#e9b75c','#f9f5d7','#9cbdbe','#d3c39b'].map(color=>new THREE.MeshBasicMaterial({color}));this.flashMaterial=new THREE.MeshBasicMaterial({color:'#fff0c3'});for(let i=0;i<96;i++){const mesh=new THREE.Mesh(geo,this.colors[0]);mesh.visible=false;scene.add(mesh);this.pool.push({mesh,velocity:new THREE.Vector3(),life:0,max:1,size:.06});}this.trail=new THREE.Mesh(new THREE.RingGeometry(1.7,1.85,16,1,-.9,2.3),new THREE.MeshBasicMaterial({color:'#ffe4a1',transparent:true,opacity:.7,side:THREE.DoubleSide,depthWrite:false}));this.trail.rotation.x=-Math.PI/2;this.trail.visible=false;scene.add(this.trail);for(let i=0;i<12;i++){const node=document.createElement('div');node.className='damage-number';node.hidden=true;document.body.appendChild(node);this.numbers.push({node,life:0,position:new THREE.Vector3()});}}
 burst(position,kind='hit',count=14){for(let i=0;i<count;i++){const p=this.pool[this.cursor++%this.pool.length];p.life=p.max=.24+Math.random()*.24;p.size=.035+Math.random()*.055;p.mesh.visible=true;p.mesh.material=this.colors[kind==='parry'?3:kind==='dust'?4:i%3];p.mesh.position.copy(position);const angle=Math.random()*Math.PI*2,speed=1.5+Math.random()*3;p.velocity.set(Math.cos(angle)*speed,kind==='dust'?.5+Math.random():1.5+Math.random()*3,Math.sin(angle)*speed);p.mesh.scale.setScalar(p.size);}}
 hit(actor,damage,kind='hit'){const at=actor.g.position.clone();at.y=1.4*(actor.g.scale.y||1);this.burst(at,kind,kind==='parry'?20:14);this.shake=Math.max(this.shake,kind==='parry'?.055:.035);this.hitStop=kind==='parry'?.075:.045;if(damage)this.number(at,String(damage));if(!actor.parts){actor.parts=[];actor.g.traverse(o=>{if(o.isMesh)actor.parts.push([o,o.material]);});}for(let [o]of actor.parts)o.material=this.flashMaterial;actor.flashTime=.085;if(!this.flashes.includes(actor))this.flashes.push(actor);}
 number(position,text){const n=this.numbers.find(n=>n.life<=0)||this.numbers[0];n.life=.75;n.position.copy(position);n.position.y+=.7;n.node.textContent=text;n.node.hidden=false;}
 update(dt,camera,player,fighter){this.shake*=Math.exp(-dt*17);this.hitStop=Math.max(0,this.hitStop-dt);for(const a of this.flashes){a.flashTime-=dt;if(a.flashTime<=0){for(let [o,m]of a.parts)o.material=m;}}this.flashes=this.flashes.filter(a=>a.flashTime>0);for(const p of this.pool){if(p.life<=0)continue;p.life-=dt;if(p.life<=0){p.mesh.visible=false;continue;}p.velocity.y-=dt*7;p.mesh.position.addScaledVector(p.velocity,dt);if(p.mesh.position.y<.05){p.mesh.position.y=.05;p.velocity.y=Math.abs(p.velocity.y)*.2;}p.mesh.scale.setScalar(p.size*Math.min(1,p.life/.13));p.mesh.rotation.x+=dt*5;p.mesh.rotation.z+=dt*7;}const action=fighter.action,move=fighter.action&&fighter.time;this.trail.visible=!!action&&fighter.time>.07&&fighter.time<.45;if(this.trail.visible){this.trail.position.copy(player.g.position);this.trail.position.y=1.25;this.trail.rotation.z=-player.g.rotation.y+fighter.time*(action==='sweep'?17:9);this.trail.scale.setScalar(action==='sweep'?1.65:1.15);this.trail.material.opacity=.6;}for(const n of this.numbers){if(n.life<=0)continue;n.life-=dt;if(n.life<=0){n.node.hidden=true;continue;}n.position.y+=dt*.8;const screen=n.position.clone().project(camera);n.node.style.transform=`translate(${(screen.x*.5+.5)*innerWidth}px,${(-screen.y*.5+.5)*innerHeight}px)`;n.node.style.opacity=Math.min(1,n.life*4);n.node.hidden=screen.z>1||screen.z<-1;}}
}
